pragma solidity >=0.8.0;

contract EventInterleaveProbe {
    event A(uint256 value);
    event B(uint256 value);

    uint256 public aLast;
    uint256 public bLast;
    uint256 public total;

    function run() public {
        emit A(1);
        emit B(9);
        emit A(2);
        aLast = 2;
        bLast = 9;
        total = 3;
    }

    function snapshot() public view returns (uint256, uint256, uint256) {
        return (aLast, bLast, total);
    }
}
